// Sound effects for the whole game, synthesized with Web Audio (no sound files, works offline). One shared
// AudioContext, made on the first sound after a tap (phone autoplay rules). Obeys the same Sounds switch as the 3D
// world (localStorage trottville-sound-v1 = 'off'). Every sound is short and quiet; nothing loops here
// (music.js plays the music). sfx('name', {pan, vol}) — unknown names are ignored.
const KEY='trottville-sound-v1';
let ctx=null,master=null,noiseBuf=null,last={};
export const soundsOn=()=>{try{return localStorage.getItem(KEY)!=='off';}catch{return true;}};
export function setSounds(on){try{localStorage.setItem(KEY,on?'on':'off');}catch{}window.dispatchEvent(new CustomEvent('trottville:sound',{detail:{on}}));}
export function audioContext(){if(!ctx){if(navigator.userActivation&&!navigator.userActivation.hasBeenActive)return null;
    try{ctx=new (window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.gain.value=.5;master.connect(ctx.destination);}catch{ctx=null;return null;}for(const n in CLIP_DATA)clip(n);}
  if(ctx.state==='suspended')ctx.resume?.();return ctx;}
function noise(){if(!noiseBuf){noiseBuf=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate);const d=noiseBuf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;}return noiseBuf;}
function out(vol,pan){const g=ctx.createGain();g.gain.value=vol;if(pan&&ctx.createStereoPanner){const p=ctx.createStereoPanner();p.pan.value=Math.max(-1,Math.min(1,pan));g.connect(p).connect(master);}else g.connect(master);return g;}
// Building blocks: a pitched blip and a filtered noise burst, each with a quick attack and a decay.
function tone(t,{f=440,f2=f,type='sine',a=.005,d=.15,v=.3,dest}){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(f,t);if(f2!==f)o.frequency.exponentialRampToValueAtTime(Math.max(20,f2),t+a+d);
  g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+a);g.gain.exponentialRampToValueAtTime(.0005,t+a+d);o.connect(g).connect(dest);o.start(t);o.stop(t+a+d+.05);}
function hiss(t,{type='bandpass',f=1200,f2=f,q=1,a=.005,d=.12,v=.3,dest}){const s=ctx.createBufferSource(),fl=ctx.createBiquadFilter(),g=ctx.createGain();s.buffer=noise();fl.type=type;fl.Q.value=q;fl.frequency.setValueAtTime(f,t);if(f2!==f)fl.frequency.exponentialRampToValueAtTime(Math.max(30,f2),t+a+d);
  g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+a);g.gain.exponentialRampToValueAtTime(.0005,t+a+d);s.connect(fl).connect(g).connect(dest);s.start(t,Math.random()*.5);s.stop(t+a+d+.05);}
const r=(a,b)=>a+Math.random()*(b-a);

// The sounds. Each gets (t = start time, o = output node, opts).
const SOUNDS={
  tap:(t,o)=>tone(t,{f:660,f2:880,type:'triangle',d:.06,v:.18,dest:o}),
  back:(t,o)=>tone(t,{f:560,f2:420,type:'triangle',d:.07,v:.15,dest:o}),
  bonk:(t,o)=>{tone(t,{f:200,f2:140,type:'square',d:.12,v:.08,dest:o});tone(t+.09,{f:150,f2:110,type:'square',d:.12,v:.07,dest:o});},
  pop:(t,o)=>tone(t,{f:420,f2:1100,type:'sine',d:.09,v:.25,dest:o}),
  chime:(t,o)=>[784,1047,1319].forEach((f,i)=>tone(t+i*.09,{f,type:'sine',d:.5,v:.16,dest:o})),
  sparkle:(t,o)=>{for(let i=0;i<6;i++)tone(t+i*.05,{f:r(1800,3200),type:'sine',d:.18,v:.07,dest:o});},
  fanfare:(t,o)=>[[523,0],[659,.12],[784,.24],[1047,.4]].forEach(([f,d],i)=>{tone(t+d,{f,type:'triangle',d:i===3?.6:.16,v:.2,dest:o});tone(t+d,{f:f/2,type:'sine',d:i===3?.6:.16,v:.1,dest:o});}),
  coin:(t,o)=>{tone(t,{f:1320,type:'square',d:.06,v:.07,dest:o});tone(t+.06,{f:1980,type:'square',d:.18,v:.07,dest:o});},
  buy:(t,o)=>{SOUNDS.coin(t,o);SOUNDS.coin(t+.1,o);hiss(t,{type:'highpass',f:5000,d:.2,v:.08,dest:o});},
  // Horse care at home.
  brush:(t,o)=>hiss(t,{type:'bandpass',f:r(2200,3000),f2:r(1400,1800),q:.8,a:.03,d:.18,v:.22,dest:o}),
  crunch:(t,o)=>{for(let i=0;i<4;i++)hiss(t+i*.07+r(0,.02),{type:'bandpass',f:r(900,1600),q:2,d:.05,v:.35,dest:o});},
  rake:(t,o)=>{hiss(t,{type:'bandpass',f:700,f2:1400,q:1.5,a:.04,d:.3,v:.3,dest:o});for(let i=0;i<5;i++)hiss(t+i*.05,{type:'highpass',f:3000,d:.02,v:.12,dest:o});},
  // A soft horse nicker: a low wobbling hum through a nasal formant.
  nicker:(t,o)=>{const lp=ctx.createBiquadFilter();lp.type='lowpass';lp.frequency.value=900;lp.Q.value=4;lp.connect(o);
    const osc=ctx.createOscillator(),g=ctx.createGain(),lfo=ctx.createOscillator(),lg=ctx.createGain();osc.type='sawtooth';osc.frequency.setValueAtTime(r(115,135),t);osc.frequency.linearRampToValueAtTime(r(95,105),t+.6);
    lfo.frequency.value=r(14,18);lg.gain.value=.5;lfo.connect(lg).connect(g.gain);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.35,t+.05);g.gain.linearRampToValueAtTime(0,t+.65);
    osc.connect(g).connect(lp);osc.start(t);lfo.start(t);osc.stop(t+.7);lfo.stop(t+.7);},
  // v110: a full whinny: a high squeal that rises, then wobbles down through two nasal formants, ending in a breathy snort.
  whinny:(t,o)=>{const f1=ctx.createBiquadFilter(),f2=ctx.createBiquadFilter(),mix=ctx.createGain();f1.type=f2.type='bandpass';f1.frequency.value=1100;f1.Q.value=3;f2.frequency.value=2400;f2.Q.value=4;mix.gain.value=1.6;f1.connect(mix);f2.connect(mix);mix.connect(o);
    const osc=ctx.createOscillator(),g=ctx.createGain(),lfo=ctx.createOscillator(),lg=ctx.createGain(),b=r(.95,1.08);osc.type='sawtooth';
    osc.frequency.setValueAtTime(620*b,t);osc.frequency.linearRampToValueAtTime(980*b,t+.18);osc.frequency.linearRampToValueAtTime(900*b,t+.4);osc.frequency.exponentialRampToValueAtTime(330*b,t+1.15);
    lfo.frequency.setValueAtTime(9,t);lfo.frequency.linearRampToValueAtTime(17,t+1.1);lg.gain.setValueAtTime(15,t);lg.gain.linearRampToValueAtTime(60,t+1.1);lfo.connect(lg).connect(osc.frequency);
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.3,t+.06);g.gain.setValueAtTime(.3,t+.5);g.gain.linearRampToValueAtTime(0,t+1.2);
    osc.connect(g);g.connect(f1);g.connect(f2);osc.start(t);lfo.start(t);osc.stop(t+1.25);lfo.stop(t+1.25);SOUNDS.snort(t+1.15,o);},
  snort:(t,o)=>{hiss(t,{type:'bandpass',f:500,f2:250,q:1,a:.02,d:.25,v:.4,dest:o});hiss(t+.05,{type:'lowpass',f:300,d:.2,v:.3,dest:o});},
  heart:(t,o)=>tone(t,{f:880,f2:1320,type:'sine',d:.2,v:.12,dest:o}),
  // Doors, shutters, tack.
  creak:(t,o)=>{const osc=ctx.createOscillator(),g=ctx.createGain(),bp=ctx.createBiquadFilter();osc.type='sawtooth';osc.frequency.setValueAtTime(r(55,70),t);osc.frequency.linearRampToValueAtTime(r(85,110),t+.5);
    bp.type='bandpass';bp.frequency.value=1100;bp.Q.value=6;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.25,t+.08);g.gain.linearRampToValueAtTime(0,t+.6);osc.connect(bp).connect(g).connect(o);osc.start(t);osc.stop(t+.65);},
  thud:(t,o)=>{tone(t,{f:110,f2:50,type:'sine',d:.25,v:.5,dest:o});hiss(t,{type:'lowpass',f:400,d:.1,v:.2,dest:o});},
  saddle:(t,o)=>{SOUNDS.creak(t,o);SOUNDS.buckle(t+.35,o);},
  happy:(t,o)=>SOUNDS.nicker(t,o),grumpy:(t,o)=>SOUNDS.snort(t,o),
  buckle:(t,o)=>{tone(t,{f:2600,type:'square',d:.03,v:.06,dest:o});tone(t+.08,{f:3100,type:'square',d:.03,v:.05,dest:o});hiss(t+.02,{type:'bandpass',f:900,q:3,d:.15,v:.12,dest:o});},
  // Riding: one hoof hit. 'clop' on hard ground, 'thump' on grass, 'wood' on boards.
  clop:(t,o)=>{tone(t,{f:r(700,850),f2:300,type:'triangle',d:.05,v:.18,dest:o});hiss(t,{type:'bandpass',f:2000,q:2,d:.03,v:.1,dest:o});},
  thump:(t,o)=>{tone(t,{f:r(120,150),f2:70,type:'sine',d:.08,v:.25,dest:o});hiss(t,{type:'lowpass',f:600,d:.06,v:.12,dest:o});},
  wood:(t,o)=>{tone(t,{f:r(380,440),f2:200,type:'triangle',d:.07,v:.2,dest:o});hiss(t,{type:'bandpass',f:1200,q:3,d:.05,v:.1,dest:o});},
  whoosh:(t,o)=>hiss(t,{type:'bandpass',f:400,f2:1800,q:.7,a:.12,d:.3,v:.3,dest:o}),
  // Races.
  beep:(t,o)=>tone(t,{f:660,type:'square',d:.15,v:.1,dest:o}),
  go:(t,o)=>tone(t,{f:1320,type:'square',d:.4,v:.12,dest:o}),
  splash:(t,o)=>{hiss(t,{type:'lowpass',f:1600,f2:400,d:.4,v:.4,dest:o});for(let i=0;i<4;i++)tone(t+r(.05,.3),{f:r(900,1600),f2:r(400,700),d:.06,v:.05,dest:o});},
};
export const SOUND_NAMES=Object.keys(SOUNDS);

// Play one. Same sound within 40 ms is skipped (so a burst of events doesn't stack into a roar).
// v111 confetti: every fanfare (quest done, badge, legend caught…) also throws a burst of confetti, sound on or off.
// One fixed canvas over the page, ~2 s of falling paper, then it removes itself. Off with ✨ Pretty effects or reduced motion.
export function confetti({x=.5,y=.35,n=110}={}){try{if(localStorage.getItem('trottville-gfx')==='lite')return;}catch{}if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const cv=document.createElement('canvas'),dpr=Math.min(2,devicePixelRatio||1),W=innerWidth,H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;Object.assign(cv.style,{position:'fixed',inset:'0',width:'100%',height:'100%',pointerEvents:'none',zIndex:'9999'});document.body.appendChild(cv);
  const g=cv.getContext('2d');g.scale(dpr,dpr);const C=['#f2c94c','#eb6f6f','#6fb1eb','#7ccf8a','#c58ae6','#ffffff','#f59fc0'];
  const P=Array.from({length:n},()=>{const a=-Math.PI/2+(Math.random()-.5)*2.2,v=7+Math.random()*9;return {x:W*x,y:H*y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,w:5+Math.random()*6,h:3+Math.random()*5,r:Math.random()*6,vr:(Math.random()-.5)*.4,c:C[Math.floor(Math.random()*C.length)],f:Math.random()*6};});
  let last=performance.now(),t=0;const step=now=>{const dt=Math.min(.05,(now-last)/1000)*60;last=now;t+=dt/60;g.clearRect(0,0,W,H);let alive=0;
    for(const p of P){p.vy+=.28*dt;p.vx*=.985;p.vy*=.985;p.x+=(p.vx+Math.sin(t*4+p.f)*.8)*dt;p.y+=p.vy*dt;p.r+=p.vr*dt;if(p.y<H+20)alive++;
      g.save();g.translate(p.x,p.y);g.rotate(p.r);g.scale(1,Math.abs(Math.cos(t*6+p.f)));g.fillStyle=p.c;g.globalAlpha=Math.max(0,Math.min(1,3.2-t));g.fillRect(-p.w/2,-p.h/2,p.w,p.h);g.restore();}
    if(alive&&t<3.2)requestAnimationFrame(step);else cv.remove();};requestAnimationFrame(step);}
export function sfx(name,{pan=0,vol=1,delay=0,rate=1}={}){if(name==='fanfare'&&!document.hidden)confetti();const make=SOUNDS[name];if((!make&&!CLIP_DATA[name])||!soundsOn()||document.hidden)return;
  const c=audioContext();if(!c)return;const now=c.currentTime;if(!delay&&last[name]&&now-last[name]<.04)return;last[name]=now;
  const al=ALIAS[name],buf=clip(al?al[0]:name);try{if(buf){const src=c.createBufferSource();src.buffer=buf;src.playbackRate.value=rate*(al?al[1]:1);src.connect(out(vol*(al?al[2]:1)*(CLIP_VOL[al?al[0]:name]||1),pan));src.start(now+.01+delay);}else if(make)make(now+.01+delay,out(vol,pan));}catch{}}

// Buttons make a soft tap everywhere (primary/secondary buttons and the round icon buttons), unless marked data-silent.
document.addEventListener?.('click',e=>{const b=e.target.closest?.('button,a.primary,a.secondary');if(!b||b.disabled||b.closest('[data-silent]')||b.dataset.silent!=null)return;
  sfx(/close|back|cancel|×/i.test(b.getAttribute('aria-label')||b.textContent||'')?'back':'tap',{vol:.8});},true);

// v129 (Yoshi picked 2026-11-15 on the Horse Sound Compare page): real recorded clips (ElevenLabs Sound Effects, mono
// 48 kbps) for whinny, snort, saddle (mount), and looping trot / canter hoofbeats. Inlined because the artifact is at its
// 512-file cap. Each is decoded once when the AudioContext starts; until then (or if decoding fails) the synth plays.
// v130 (round 2, all "use new"): soft nicker, plus looping walk hoofbeats on wooden bridges and on cobbles.
const CLIP_VOL={whinny:.9,snort:.8,saddle:.8,trot:.5,canter:.5,nicker:.8,bridge:.5,cobble:.5,happy:.85,grumpy:.85};
// v131 (Yoshi): horse voices pitch by size in 3 levels, on the clips only (hoofbeats and saddle stay unpitched):
// big (size ≥ 1.05: drafts, big warmbloods) as recorded; medium ×1.19 (+3 semitones); small (< .82: ponies, minis, foals) ×1.41 (+6).
export const voiceRate=size=>{const s=Number(size)||1;return s>=1.05?1:s>=.82?1.19:1.41;};
// Brushing moods reuse the recorded clips until Yoshi picks the round-3 mood clips: happy = a brighter nicker, grumpy = a sharp, fast snort.
// v140 (Yoshi's round-3 re-paste): happy = the recorded clip; grumpy = "keep now" = the sharp, fast snort alias.
const ALIAS={grumpy:['snort',1.25,1]};
const buffers={},decoding={};
function clip(name){if(buffers[name])return buffers[name];if(!ctx||decoding[name]||!CLIP_DATA[name])return null;decoding[name]=1;
  try{const bytes=Uint8Array.from(atob(CLIP_DATA[name]),ch=>ch.charCodeAt(0)).buffer;ctx.decodeAudioData(bytes,b=>{buffers[name]=b;trimOf(name,b);},()=>{});}catch{}return null;}
// Hoofbeat loop while riding: hoofLoop('trot'|'canter'|'bridge'|'cobble', rate) each frame keeps it going (rate follows speed); hoofLoop(null) fades it out.
// Returns true while the loop is playing, so the caller can skip the synth hoof hits.
// v132: loop points skip the MP3 encoder padding (silent samples at each end), so loops don't tick at the seam.
const trims={};
function trimOf(name,b){const d=b.getChannelData(0);let i=0,j=d.length-1;while(i<j&&Math.abs(d[i])<1e-4)i++;while(j>i&&Math.abs(d[j])<1e-4)j--;trims[name]=[i/b.sampleRate,(j+1)/b.sampleRate];}
// Clips another module brings (the world's ambience, doors, footsteps and voices live in world-sky.js so the home page stays light).
export function registerClips(data,vol={}){Object.assign(CLIP_DATA,data);Object.assign(CLIP_VOL,vol);if(ctx)for(const n in data)clip(n);}
// v132 ambient loops by channel (weather, places, footsteps): ambLoop(channel, name|null, gain, rate) every frame.
// A new name on a channel crossfades; gain/rate glide; null or ~0 gain fades out. Obeys the Sounds switch and hidden tabs.
const amb={};
function fadeOut(a,t){try{const n=ctx.currentTime;a.g.gain.cancelScheduledValues(n);a.g.gain.setValueAtTime(a.g.gain.value,n);a.g.gain.setTargetAtTime(0,n,t/3);a.src.stop(n+t*2);}catch{}}
export function ambLoop(ch,name,gain=1,rate=1){
  if(!ctx||!soundsOn()||document.hidden){ambStop();return false;}
  let a=amb[ch];const want=name&&gain>.002?name:null;
  if(a&&a.name!==want){fadeOut(a,.9);delete amb[ch];a=null;}
  if(!want)return false;
  if(!a){const buf=clip(want);if(!buf)return false;const src=ctx.createBufferSource(),g=ctx.createGain(),tr=trims[want]||[0,buf.duration];src.buffer=buf;src.loop=true;src.loopStart=tr[0];src.loopEnd=tr[1];
    g.gain.value=0;src.connect(g).connect(master);src.start(ctx.currentTime,tr[0]+Math.random()*(tr[1]-tr[0])*.9);a=amb[ch]={name:want,src,g,v:-1,r:-1};}
  const v=gain*(CLIP_VOL[want]||1);if(Math.abs(v-a.v)>.004){a.v=v;a.g.gain.setTargetAtTime(v,ctx.currentTime,a.r<0?.5:.3);}
  if(Math.abs(rate-a.r)>.01){a.r=rate;a.src.playbackRate.setTargetAtTime(rate,ctx.currentTime,.15);}
  return true;}
export function ambStop(){for(const k in amb){if(ctx)fadeOut(amb[k],.3);delete amb[k];}}
export const ambNow=()=>Object.fromEntries(Object.entries(amb).map(([k,a])=>[k,a.name]));   // test hook
// One wordless voice sound when an NPC starts talking (no words; one per bubble, 1.2 s cooldown). who: woman|man|kid,
// mood: greet|question|happy|think. rate varies a little per character so everyone sounds a bit different.
let lastVoice=0;
export function npcVoice(who,mood,{rate=1,vol=1,pan=0,delay=0}={}){const n=performance.now();if(n-lastVoice<1200)return;lastVoice=n;sfx('v_'+who+'_'+mood,{rate,vol,pan,delay});}
let hoof=null;export const hoofNow=()=>hoof?.name||null;   // test hook
export function hoofLoop(name,rate=1){
  if(!name||!soundsOn()||document.hidden||!ctx){if(hoof&&ctx){const h=hoof;hoof=null;try{h.g.gain.setTargetAtTime(0,ctx.currentTime,.06);h.src.stop(ctx.currentTime+.4);}catch{}}return false;}
  const buf=clip(name);if(!buf)return false;if(hoof&&hoof.name!==name)hoofLoop(null);
  if(!hoof){const src=ctx.createBufferSource(),g=ctx.createGain();src.buffer=buf;src.loop=true;if(trims[name]){src.loopStart=trims[name][0];src.loopEnd=trims[name][1];}g.gain.value=0;g.gain.setTargetAtTime(CLIP_VOL[name],ctx.currentTime,.06);src.connect(g).connect(master);src.start(ctx.currentTime,Math.random()*buf.duration);hoof={name,src,g};}
  hoof.src.playbackRate.setTargetAtTime(Math.max(.8,Math.min(1.25,rate)),ctx.currentTime,.15);return true;}
document.addEventListener?.('visibilitychange',()=>{if(document.hidden){hoofLoop(null);ambStop();}});
globalThis.window?.addEventListener?.('trottville:sound',e=>{if(!e.detail?.on){hoofLoop(null);ambStop();}});
const CLIP_DATA={"whinny":"","snort":"","saddle":"","trot":"","canter":"","nicker":"","bridge":"","cobble":"","happy":""};
